import{_ as n,C as r,o as i,c as s,a6 as c,E as l,j as a,a as t}from"./chunks/framework.CKIbuWFA.js";const g=JSON.parse('{"title":"Prepare collaboration and team access","description":"","frontmatter":{"title":"Prepare collaboration and team access","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"en","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","translationRevision":"4a97f64b6bdc818ebb8d16eec1e67d95a2d0eae0b75f7cfd5c1493bf27244684","order":30},"headers":[],"relativePath":"en/user/cloud/collaboration.md","filePath":"en/user/cloud/collaboration.md","lastUpdated":1794611623000}'),d={name:"en/user/cloud/collaboration.md"};function p(u,e,h,m,b,f){const o=r("DemoFrame");return i(),s("div",null,[e[0]||(e[0]=c('<h1 id="prepare-collaboration-and-team-access" tabindex="-1">Prepare collaboration and team access <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to &quot;Prepare collaboration and team access {#prepare-collaboration-and-team-access}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Goal and prerequisites {#goal-and-prerequisites}&quot;">​</a></h2><p>Grant another operator a defined role while retaining owner control. You need a capable desktop host and a deliberate choice between local/native collaboration and account-based Teams. Teams also needs <a href="./account.html">Cloud sign-in</a> and matching deployed service support. Start with read-only access and a nonproduction setup.</p><h2 id="configure-owner-access" tabindex="-1">Configure owner access <a class="header-anchor" href="#configure-owner-access" aria-label="Permalink to &quot;Configure owner access {#configure-owner-access}&quot;">​</a></h2><ol><li>Open <strong>Settings → Collaboration</strong>. Inspect connection status and enable/configure the intended listener or gateway through its controls.</li><li>Review allowed origins and the access matrix before creating an invitation. Choose only the areas, operations and resources the operator needs.</li><li>Create an invitation and deliver its private link/token through a trusted channel. An invitation is not the same as an approved active session.</li><li>Inspect pending requests and the requested grant. Approve only the expected operator, then confirm their visible identity and connection.</li><li>Use the access inspector to review later grant changes. Revoke invitations, identities or sessions when their access is no longer needed.</li></ol><p>Delegated definition editing, adopting a definition as owner and approving delegated execution are distinct decisions. Read the saved source, referenced actions and permissions in the specific review. A definition preview alone does not authorize an effect.</p><h2 id="prepare-an-account-based-team" tabindex="-1">Prepare an account-based team <a class="header-anchor" href="#prepare-an-account-based-team" aria-label="Permalink to &quot;Prepare an account-based team {#prepare-an-account-based-team}&quot;">​</a></h2><p>When <strong>Settings → Teams</strong> is offered, create a named team and select it. Enroll <strong>this PC</strong> as a host with a recognizable device label, then use <strong>Start serving</strong> and inspect its link state. Creation and local-host enrollment are wired in the frontend; they are separate from inviting a teammate. A controller device has its own enrollment role.</p><p>Choose a recipient, role and invitation lifetime, then review incoming requests, members and devices. The nickname search flow requires a separately deployed backend endpoint and may be unavailable on the current service. Do not assume a failed search means the person has no account, and do not substitute an arbitrary ID to bypass selection.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Expected result and status {#expected-result-and-status}&quot;">​</a></h2><p>Owner access controls and frontend team creation/enrollment exist. The complete remote collaboration workflow is experimental: real two-PC LIVE operation, production nickname lookup, NAT/relay behavior and every platform/effect recovery path are not established here. A ready link alone does not prove end-to-end permission enforcement for your intended action.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For stale grants or host revisions, reload and review again. For unconfirmed commands, inspect the recorded outcome before retrying. Stop serving or revoke access when ending a session. Keep invitation tokens and credentials out of public <a href="./../preferences/troubleshooting.html">diagnostic reports</a>.</p>',13)),l(o,{scenario:"collaboration",locale:"en",title:"Demo: collaboration"}),e[1]||(e[1]=a("h2",{id:"operational-details",tabindex:"-1"},[t("Operational details "),a("a",{class:"header-anchor",href:"#operational-details","aria-label":'Permalink to "Operational details {#operational-details}"'},"​")],-1)),e[2]||(e[2]=a("p",null,[t("After joining or approving Teams access, the host must confirm the current native permission revision. "),a("code",null,"pendingHost"),t(" means this is still pending; an active transport or team membership alone grants no native access. Reload after a permission change and recheck host/device status. Observer is read-oriented; moderator adds selected operational controls, automationEditor adds selected editing, and custom requires an explicit reviewed policy. None grants unrestricted scripts or external effects. See "),a("a",{href:"./../../developer/collaboration.html#operational-details"},"the role and confirmation contract"),t(" if available controls do not explain a denial.")],-1))])}const w=n(d,[["render",p]]);export{g as __pageData,w as default};
